  var third=wear(h,a,3);counter(a);counter(b);transfer(h,a,b,third);h.assertTrue(!RepairSavedData.get(server).evidence().get(wearId(third)).wearer().equals(b.getUUID()),"Third current owner is deliberately different from original wearer");
