 static void resume(GameTestHelper h,ServerPlayer smith,CompoundTag saved,Path proof)throws Exception{
  var store=CommerceService.store(smith.server);if(store.professions(smith.getUUID()).track(Profession.BLACKSMITH).completedQuestIds().contains(SmithCommunityForge.FINAL)){h.assertTrue(store.professions(smith.getUUID()).track(Profession.BLACKSMITH).xp()==saved.getLong("xp")+900&&store.serviceWork().jobs(smith.getUUID(),ServiceWorkState.SMITH)==3&&store.itemMailbox(saved.getUUID("customerA")).size()==2&&store.itemMailbox(saved.getUUID("customerB")).size()==1,"Final real service quest/300XP/three once-only returns and all customer deliveries survive native restart");CommerceService.verifyReceipt(smith);h.assertTrue(smith.serverLevel().getEntity(BlacksmithRepairRuntime.forge(smith).npc())!=null,"Original paid forge NPC survives");h.assertTrue(smith.server.getCommands().getDispatcher().execute("kingdom admin profession services "+smith.getGameProfile().getName(),smith.server.createCommandSourceStack())==1,"Real OP2console bounded service inspection works");boolean denied=false;try{smith.server.getCommands().getDispatcher().execute("kingdom admin profession services "+smith.getGameProfile().getName(),smith.createCommandSourceStack());}catch(com.mojang.brigadier.exceptions.CommandSyntaxException expected){denied=true;}h.assertTrue(denied,"Ordinary player cannot inspect admin service records");com.mojang.logging.LogUtils.getLogger().info("OWNER_REPAIR_SERVICE_RESTART_PASSED: completed three native returned jobs/two explicit owners/canonical spent identities/native receipts/300XP/original forgeNPC restore");h.succeed();return;}
  h.assertTrue(store.serviceWork().jobs(smith.getUUID(),ServiceWorkState.SMITH)==2&&store.itemMailbox(saved.getUUID("customerA")).size()==2&&smith.server.getPlayerList().getPlayer(saved.getUUID("customerB"))==null,"Actual partial restart retains two returns and third owner can remain offline");
  smith.giveExperienceLevels(40);var result=repair(h,smith,saved.getUUID("thirdWear"));var id=outputId(result);h.assertTrue(id!=null,"Persisted genuine third input and explicit current-owner consent authorize actual paid native output after restart");counter(smith);var q=ProfessionService.review(smith,"service_return:"+id);ProfessionService.confirm(smith,q.nonce());h.assertTrue(ServiceWorkService.ready(smith)&&store.itemMailbox(saved.getUUID("customerB")).size()==1,"Offline current customer receives exact recoverable repaired equipment; all3returned jobs/two owners now qualify");q=ProfessionService.review(smith,"quest:"+ServiceWorkState.SMITH);ProfessionService.confirm(smith,q.nonce());h.assertTrue(store.professions(smith.getUUID()).track(Profession.BLACKSMITH).xp()==saved.getLong("xp")+300,"Exactly300earned service XP, no unearned Master rank or equipment");completeMaster(h,smith);h.assertTrue(store.professions(smith.getUUID()).track(Profession.BLACKSMITH).xp()==4800&&store.professions(smith.getUUID()).rank(Profession.BLACKSMITH,ProfessionService.quests())==ProfessionRank.MASTER,"All24real native Blacksmith proofs earn4800XP/Master without equipment mint");CommerceService.checkpoint(smith);var restored=EconomyStore.open(smith.server.getWorldPath(LevelResource.ROOT).resolve("data"));h.assertTrue(restored.professions(smith.getUUID()).equals(store.professions(smith.getUUID()))&&restored.serviceWork().customers(smith.getUUID(),ServiceWorkState.SMITH)==2,"Canonical reopen retains every prior proof/explicit owner/once-only output use");com.mojang.logging.LogUtils.getLogger().info("OWNER_REPAIR_SERVICE_COMPLETE_PASSED: actual third native repair after restart/offline explicit current owner distinct from first wearer/permanent physical return/native receipt/3jobs2owners/real funded Master service/confirmed live final assessment/all24earned4800XP-Master; private5period-goal1only, no default-duration or source/quest/XP/rank injection");h.succeed();
 }
 static void completeMaster(GameTestHelper h,ServerPlayer smith)throws Exception{
  BlacksmithRepairRuntime.ensureWorkingAnvil(h,smith);counter(smith);var store=CommerceService.store(smith.server);var config=smith.server.getWorldPath(LevelResource.ROOT).resolve("serverconfig/kingdomsmp-commission-quests.json");CommissionQuestRules.get(smith.server);var root=com.google.gson.JsonParser.parseString(Files.readString(config)).getAsJsonObject();root.getAsJsonObject("goals").addProperty("kingdom_smp:blacksmith/m06",1);Files.writeString(config,new com.google.gson.Gson().toJson(root));CommissionQuestRules.clear(smith.server);
  int slot=-1;for(int i=0;i<36;i++)if(smith.getInventory().getItem(i).isEmpty()){slot=i;break;}h.assertTrue(slot>=0,"Raw contract supply uses free space without erasing earned tools");smith.getInventory().setItem(slot,new ItemStack(Items.IRON_INGOT,64));int before=smith.getInventory().countItem(Items.IRON_INGOT);var job=ContractService.review(smith,"blacksmith/daily");ContractService.confirm(smith,job.nonce());h.assertTrue(smith.getInventory().countItem(Items.IRON_INGOT)==before-job.terms().quantity(),"Real native Master service consumes full actual terms and uses finite reward mail");var q=ProfessionService.review(smith,"quest:kingdom_smp:blacksmith/m06");ProfessionService.confirm(smith,q.nonce());
  var center=ConstructionService.lodge(smith.server).origin().offset(400,5,160);for(int x=(center.getX()-9)>>4;x<=(center.getX()+9)>>4;x++)for(int z=(center.getZ()-9)>>4;z<=(center.getZ()+9)>>4;z++)smith.serverLevel().getChunk(x,z);
  var hut=ConstructionService.store(smith.server).reward(ConstructionService.STARTING_HUT).orElseThrow();var admin=ClaimRuntimeTests.vanillaPlayer(smith.serverLevel(),hut.owner(),hut.ownerName());admin.moveTo(center.getX()+.5,center.getY(),center.getZ()+.5);smith.moveTo(center.getX()+1.5,center.getY(),center.getZ()+.5);smith.server.getPlayerList().op(admin.getGameProfile());try{var inspect=ProfessionInspectionService.review(admin,smith,SmithCommunityForge.FINAL,center,"Inspected actual Master forging compatible native repairs and customer returns");ProfessionInspectionService.confirm(admin,inspect);}finally{smith.server.getPlayerList().deop(admin.getGameProfile());}
 }
 static ItemStack wear(GameTestHelper h,ServerPlayer owner,int n)throws Exception{var at=ConstructionService.lodge(owner.server).origin().offset(700+n*16,0,500);owner.serverLevel().getChunkAt(at);h.assertTrue(owner.serverLevel().getBlockState(at).isAir(),"Private raw native-wear terrain never replaces existing property");owner.serverLevel().setBlock(at.below(),Blocks.STONE.defaultBlockState(),3);owner.serverLevel().setBlock(at,Blocks.STONE.defaultBlockState(),3);var tool=new ItemStack(Items.IRON_PICKAXE);if(n==0)tool.enchant(owner.registryAccess().lookupOrThrow(net.minecraft.core.registries.Registries.ENCHANTMENT).getOrThrow(net.minecraft.world.item.enchantment.Enchantments.EFFICIENCY),2);int hotbar=-1;for(int i=0;i<9;i++)if(owner.getInventory().getItem(i).isEmpty()){hotbar=i;break;}h.assertTrue(hotbar>=0,"Customer native wear fixture preserves existing equipment");owner.getInventory().selected=hotbar;owner.setItemInHand(InteractionHand.MAIN_HAND,tool);BlacksmithRepairRuntime.near(owner,at);h.assertTrue(owner.gameMode.destroyBlock(at)&&tool.getDamageValue()>0&&wearId(tool)!=null,"Actual successful permitted native player break pays real durability and creates tracked wear");return tool;}
 static void counter(ServerPlayer p){BlacksmithRepairRuntime.counter(p);}
 static void transfer(GameTestHelper h,ServerPlayer from,ServerPlayer to,ItemStack expected){counter(from);counter(to);int slot=-1;for(int i=0;i<36;i++)if(ItemStack.matches(from.getInventory().getItem(i),expected)){slot=i;break;}h.assertTrue(slot>=0,"Actual current owner has original physical input before transfer");var stack=from.getInventory().getItem(slot);from.getInventory().setItem(slot,ItemStack.EMPTY);var entity=from.drop(stack,false);h.assertTrue(entity!=null,"Real native item drop");entity.setNoPickUpDelay();entity.playerTouch(to);h.assertTrue(entity.isRemoved()&&java.util.stream.IntStream.range(0,36).anyMatch(i->ItemStack.matches(to.getInventory().getItem(i),expected)),"Actual native pickup transfers the exact lineage without copying client tags or counts");}
 static ItemStack repair(GameTestHelper h,ServerPlayer smith,UUID wear)throws Exception{int slot=-1;for(int i=0;i<36;i++)if(wear.equals(wearId(smith.getInventory().getItem(i)))){slot=i;break;}h.assertTrue(slot>=0,"Provider really holds consenting customer's unique input");var tool=smith.getInventory().getItem(slot);smith.getInventory().setItem(slot,ItemStack.EMPTY);var result=BlacksmithRepairRuntime.repair(h,smith,tool);BlacksmithRepairRuntime.ensureWorkingAnvil(h,smith);return result;}
 static UUID wearId(ItemStack s){var t=s.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag().getCompound(RepairService.KEY);return t.hasUUID("id")?t.getUUID("id"):null;}
 static UUID outputId(ItemStack s){var t=s.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag().getCompound(ServiceWorkService.KEY);return t.hasUUID("id")?t.getUUID("id"):null;}
